// internal/search/weaviate.go

type WeaviateClient struct {
    client *weaviate.Client
}

type ChunkResult struct {
    Text        string   `json:"text"`
    ChunkID     string   `json:"chunk_id"`
    DocumentID  int64    `json:"document_id"`
    PageNum     int      `json:"page_num"`
    SectionPath []string `json:"section_path"`
    Score       float64  `json:"score"`
}

// CreateSchema creates the Chunk class if it doesn't exist
func (w *WeaviateClient) CreateSchema() error

// InsertChunk adds a chunk to Weaviate (embedding auto-generated)
func (w *WeaviateClient) InsertChunk(chunk ChunkResult) (string, error)

// HybridSearch performs BM25+vector search for relevant chunks
func (w *WeaviateClient) HybridSearch(query string, limit int, alpha float64) ([]ChunkResult, error)

// DeleteByDocumentID removes all chunks for a document
func (w *WeaviateClient) DeleteByDocumentID(documentID int64) error
